public static void main(String[] args) {
    Scanner sc = new Scanner(System.in);
    int n = sc.nextInt();
    int[] q = new int[n];
    int[] a = new int[n];
    int[] b = new int[n];
    int maxa = Integer.MAX_VALUE;
    int res = 0;
    for (int i = 0; i < n; i++) {
        q[i] = sc.nextInt();
    }
    for (int i = 0; i < n; i++) {
        a[i] = sc.nextInt();
    }
    for (int i = 0; i < n; i++) {
        b[i] = sc.nextInt();
    }
    for (int i = 0; i < n; i++) {
        if (a[i] > 0) {
            maxa = Math.min(maxa, q[i] / a[i]);
        }
    }
    for (int i = 0; i <= maxa; i++) {
        int currentMaxb = Integer.MAX_VALUE;
        for (int j = 0; j < n; j++) {
            if (b[j] > 0) {
                currentMaxb = Math.min(currentMaxb, (q[j] - a[j] * i) / b[j]);
            }
        }
        res = Math.max(res, i + currentMaxb);
    }
    System.out.println(res);
}
